SELECT "nct", "author", "year", "pubmed_id", "trial_phase", "treatment_regimen", "name_of_ici", "class_of_ici", "type_of_combination", "control_regimen", "type_of_control", "cancer_type", "lines_of_treatment", "clincal_setting_in_relation_to_surgery", "primary_endpoint", "priamry_multiple_composite_or_co_primary_endpoints", "secondary_endpoint", "is_pd_l1_positivity_inclusion_criteria", "is_any_other_biomarker_used_for_inclusion", "type_of_follow_up_given", "follow_up_duration_for_primary_endpoint_s_in_months_overall", "follow_up_duration_for_primary_endpoint_s_in_months_rx", "follow_up_duration_for_primary_endpoint_s_in_months_control" FROM public."clinical_trials" WHERE "trial_phase" = 'Phase 2' AND "class_of_ici" = 'PD1' AND "cancer_type" = 'Breast' AND "type_of_combination" = 'Monotherapy' AND "name_of_ici" IS NOT NULL;